 lookup={v[1]:v[2][1]for v in symbol_rows((root/'conker/build/conker.us.elf').read_bytes())};words=bound_blob(fixed,freferences,{nm:(lookup[nm]if nm in lookup else int(nm[2:],16))for es in freferences.values()for _,nm in es});truth=(root/'conker/conker.us.bin').read_bytes()[0x51664:0x51664+324];assert struct.pack('>81I',*words)==truth
